body:
I think I figured out the problem.
1. I have multiple entry points, one of them is called `Cards.js`
2. At build-time, webpack outputs `Cards.js`, `Common.js` and JS files for other entry points.
3. At watch-time, I modify `Cards.js` and Webpack outputs:

```
[00:11:48] Compiling webpack config ~\Documents\realestate\frontend\webpack.config.js
[00:11:48] 
              Asset  Size  Chunks             Chunk Names
Authentications.css   335       4  [emitted]  Authentications
          Index.css   510       2  [emitted]  Index
          Cards.css   531       3  [emitted]  Cards
         Common.css   190       5  [emitted]  Common
```

Fortunately, I've got http://www.browsersync.io/ enabled, and its plugin outputs:

```
[BS] 4 files changed (Authentications.css, Index.css, Cards.css, Common.css)
```

Meaning, in step 3 Webpack is modifying `Cards.js` but not `Common.js`. This means that module IDs change in `Cards.js` which will cause `Common.js` to break.

Here is a copy of my `webpack.config.js`:

```
var buildConfig = require("./buildConfig.js");
var namespace = "com/realestate/frontend/";
var srcEntryDir = buildConfig.srcDir + namespace + "page/";
var targetEntryDir = buildConfig.targetDir + namespace + "page/";
var path = require("path");
var resolve =
{
    alias: {}
};
var noParse = [];
/**
 * @param {String} literal the literal string to escape
 * @return {String} a regular expression containing the literal string
 * @see http://stackoverflow.com/a/6969486/14731
 */
function escapeRegExp(literal)
{
    return literal.replace(/[\-\[\]\/\{\}\(\)\*\+\?\.\\\^\$\|]/g, "\\$&");
}

/**
 * Indicates that a dependency won't be changing at runtime (improves performance).
 *
 * @param {String} name the module name
 * @param {String} relativePath the dependency path
 * @see http://christianalfoni.github.io/javascript/2014/12/13/did-you-know-webpack-and-react-is-awesome.html
 */
function addStaticDependency(name, relativePath)
{
    resolve.alias[name] = path.resolve(relativePath);
    noParse.push(new RegExp(escapeRegExp(relativePath) + "$"));
}

/**
 * Registers a webjar.
 *
 * @param {String} name the webjar name
 * @param {String} relativePath the webjar path relative to the "webjars" directory
 * @see http://www.webjars.org/
 */
function addWebjar(name, relativePath)
{
    addStaticDependency("webjars/" + name, "target/webjars/META-INF/resources/webjars/" + relativePath);
}

addWebjar("log4javascript.js", "log4javascript/1.4.10/log4javascript.js");
addWebjar("prefixfree.js", "prefixfree/b44a065/prefixfree.js");
addWebjar("cowwoc-alphanum-sort.js", "cowwoc-alphanum-sort/1.0.0/alphanum-sort.js");
addWebjar("cowwoc-jquery-address.js", "cowwoc-jquery-address/1.6/cowwoc-jquery-address.js");
var webpack = require("webpack");
// See https://github.com/petehunt/webpack-howto
var commonsPlugin = new webpack.optimize.CommonsChunkPlugin(
{
    name: "Common",
    filename: "Common.js",
    minChunks: 2
});
var dedupePlugin = new webpack.optimize.DedupePlugin();
var ExtractTextPlugin = require("extract-text-webpack-plugin");
var fontPath = "[path]/[name].[ext]";
var imagePath = "[path]/[name].[ext]";
var cssPath = "[name].css";
var context = srcEntryDir;
var extractTextPlugin = new ExtractTextPlugin(cssPath);

module.exports =
{
    resolve: resolve,
    entry:
    {
        Authentications: srcEntryDir + "Authentications.js",
        Cards: srcEntryDir + "Cards.js",
        Index: srcEntryDir + "Index.js",
        Properties: srcEntryDir + "Properties.js",
        Users: srcEntryDir + "Users.js"
    },
    output:
    {
        path: path.resolve(targetEntryDir),
        // Template based on "entry" keys
        filename: "[name].js"
    },
    module:
    {
        noParse: noParse,
        loaders:
        [
            {
                test: /\.woff$/,
                loader: "url-loader?limit=10000&mimetype=application/font-woff&name=" + fontPath + "&context=" + context
            },
            {
                test: /\.ttf$/,
                loader: "url-loader?limit=10000&mimetype=application/octet-stream&name=" + fontPath + "&context=" + context
            },
            {
                test: /\.eot$/,
                loader: "file-loader?name=" + fontPath + "&context=" + context
            },
            {
                test: /\.svg$/,
                loader: "url-loader?limit=10000&mimetype=image/svg+xml&name=" + imagePath + "&context=" + context
            },
            {
                test: /\.png$/,
                loader: "url-loader?limit=10000&mimetype=image/png&name=" + imagePath + "&context=" + context
            },
            {
                test: /\.css$/,
                loader: extractTextPlugin.extract("style-loader", "css-loader")
            },
            {
                test: /\.scss$/,
                // use ! to chain loaders
                loader: extractTextPlugin.extract("style-loader", "css-loader!sass-loader")
            },
            {
                test: /\.json$/,
                loader: "json"
            }
        ]
    },
    plugins:
    [
        commonsPlugin,
        dedupePlugin,
        extractTextPlugin
    ],
    externals:
    {
        // Push 3rd-party libraries out to CDN.
        // @see http://stackoverflow.com/a/558494/14731
        stripe: "Stripe",
        jquery: "$",
        q: "Q",
        URIjs: "URI",
        "stacktrace-js": "printStackTrace",
        log4javascript: "log4javascript"
    },
    debug: true
};
```

I believe that in order to fix this issue, webpack needs to rewrite `Common.js` on watch.
